<?php
namespace App\Domain\AI\Knowledge\Services;use App\Domain\AI\Agents\Services\AiLifecycleAuthorization;use App\Domain\AI\Knowledge\Data\KnowledgeContentData;use App\Domain\AI\Knowledge\Enums\{KnowledgeSourceStatus,KnowledgeVersionStatus};use App\Domain\AI\Knowledge\Exceptions\{ArchivedKnowledgeSourceException,KnowledgeVersionConflictException};use App\Domain\AI\Knowledge\Models\{KnowledgeSource,KnowledgeSourceVersion};use App\Domain\AI\Knowledge\Support\KnowledgeConstraintClassifier;use App\Domain\AI\Support\CanonicalJsonHasher;use App\Models\User;use Illuminate\Database\QueryException;use Illuminate\Support\Facades\DB;
final class CreateKnowledgeRevisionService{public function __construct(private AiLifecycleAuthorization$auth,private CanonicalJsonHasher$hasher){}public function create(User$actor,KnowledgeSource$source,KnowledgeContentData$data):KnowledgeSourceVersion{try{return DB::transaction(function()use($actor,$source,$data){$a=$this->auth->authorize($actor);$locked=KnowledgeSource::query()->lockForUpdate()->findOrFail($source->id);if($locked->status!==KnowledgeSourceStatus::Active)throw new ArchivedKnowledgeSourceException('Archived knowledge cannot receive revisions.');if($locked->type!==$data->type)throw new \DomainException('Knowledge source cannot receive this revision.');$next=(int)KnowledgeSourceVersion::query()->where('knowledge_source_id',$locked->id)->lockForUpdate()->max('version_number')+1;$v=new KnowledgeSourceVersion();$v->knowledge_source_id=$locked->id;$v->version_number=$next;$v->status=KnowledgeVersionStatus::Draft;$v->content=$data->content;$v->checksum=$this->hasher->hash($data->content);$v->created_by_user_id=$a->actorUserId;$v->save();return$v;});}catch(QueryException$e){if(KnowledgeConstraintClassifier::isRevisionNumberCollision($e))throw new KnowledgeVersionConflictException('A concurrent knowledge revision already allocated this version.',0,$e);throw$e;}}}
